-- AI: fixed read-only metadata, no pupil/account values. Original custodian only.
SELECT current_database() AS database_name,session_user::text AS login,current_user::text AS actor,(pg_control_system()).system_identifier::text AS system_identifier;
SELECT p.oid::regprocedure::text AS signature,encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex') AS definition_sha256,pg_get_userbyid(p.proowner) AS owner,p.prosecdef,p.proconfig,p.proacl::text AS acl,
 has_function_privilege('n88_backend',p.oid,'EXECUTE') AS backend_execute,has_function_privilege('anon',p.oid,'EXECUTE') AS anon_execute,has_function_privilege('authenticated',p.oid,'EXECUTE') AS authenticated_execute
FROM pg_proc p WHERE (p.pronamespace='rakeezx'::regnamespace AND p.proname IN ('apply_sync_v2_mutation','apply_sync_v2_mutation_before_student_0029')) OR (p.pronamespace='n88_private'::regnamespace AND (p.proname ~ '^v2_[a-f0-9]{24}$' OR p.proname IN ('v2_runtime_identity_1031','v2_writer_capture_1031','v2_writer_delete_children_1031','v2_writer_finalize_domain_1031','v2_writer_complete_1031'))) ORDER BY signature LIMIT 22;
SELECT rolname,rolcanlogin,rolsuper,rolbypassrls,rolcreaterole,rolcreatedb,rolinherit,rolconfig FROM pg_roles WHERE rolname IN ('n88_backend','n88_v2_guard','n88_v2_runtime') ORDER BY rolname;
SELECT pg_get_userbyid(roleid) AS role_name,pg_get_userbyid(member) AS member_name,pg_get_userbyid(grantor) AS grantor,admin_option,inherit_option,set_option FROM pg_auth_members WHERE roleid='n88_v2_guard'::regrole AND member IN ('postgres'::regrole,'n88_backend'::regrole) ORDER BY grantor;
SELECT c.relname,c.relrowsecurity,c.relforcerowsecurity,pg_get_userbyid(c.relowner) AS owner,has_any_column_privilege('n88_backend',c.oid,'SELECT,INSERT,UPDATE,REFERENCES') AS backend_columns,has_table_privilege('n88_backend',c.oid,'DELETE,TRUNCATE,TRIGGER') AS backend_table FROM pg_class c WHERE c.relnamespace='n88_private'::regnamespace AND c.relname IN ('publication_v2_scopes','publication_v2_items','publication_v2_high_water','publication_v2_receipts') ORDER BY c.relname;
